/* ── Open-path timing ────────────────────────────────────────── */

/* Where the time goes when a streaming session is opened.
 *
 * This exists because the open path had no instrumentation at all and the two
 * syslog lines it did emit -- "TLS connected" at the end of asr_tls_connect()
 * and "WebSocket upgrade OK" at the end of ws_upgrade() -- bracket only the
 * cheap half.  A board log of 2026-09-09 could be read for 176 ms of upgrade
 * and request work and for nothing before it, because the first line is printed
 * after the credential read, the DRBG seed, the name resolution, the TCP
 * connect and the whole TLS handshake have already happened.  That prefix is
 * precisely the part a connection cache or a pre-connect would remove, so it is
 * the one number worth having and the only one that was missing.
 *
 * connect_ms covers resolution and the TCP round trip together, which is how
 * mbedtls_net_connect() bundles them.  Splitting it means resolving separately
 * and handing the address on as a literal, a change to how the connection is
 * made rather than to what is recorded about it, and it is not worth making
 * until this figure says the two are where the time is.
 */

struct asr_open_timing_s {
    uint32_t seed_ms;      /* mbedtls_ctr_drbg_seed, entropy included */
    uint32_t connect_ms;   /* name resolution and the TCP connect */
    uint32_t handshake_ms; /* config, setup and mbedtls_ssl_handshake */
    bool proxied;          /* went through a CONNECT tunnel */
};

static uint32_t asr_now_ms(void)
{
    struct timespec ts;

    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return 0;
    }

    return (uint32_t)((uint64_t)ts.tv_sec * 1000u
        + (uint64_t)(ts.tv_nsec / 1000000));
}

/* ── TLS connect / free ──────────────────────────────────────── */

static int asr_tls_connect(asr_tls_ctx_t* ctx,
    const char* host, const char* port,
    struct asr_open_timing_s* timing)
{
    int ret;
    uint32_t mark;
    mbedtls_ssl_init(&ctx->ssl);
    mbedtls_ssl_config_init(&ctx->cfg);
    mbedtls_net_init(&ctx->net);
    mbedtls_ctr_drbg_init(&ctx->ctr_drbg);
    const char* pers = "volc_asr";
    mark = asr_now_ms();
    ret = mbedtls_ctr_drbg_seed(&ctx->ctr_drbg, asr_entropy_func,
        NULL, (const unsigned char*)pers,
        strlen(pers));
    if (timing != NULL) {
        timing->seed_ms = asr_now_ms() - mark;
    }
    if (ret != 0) {
        syslog(LOG_ERR, "[%s] ctr_drbg_seed: -0x%04x\n", TAG, -ret);
        return -EIO;
    }

